/* the leaf of a scalar value cp (not a surrogate, at most U+10FFFF) */
const unsigned char *utf8leaf(unsigned int cp)
{
    unsigned int b = utf8top[cp >> 11];
    b = utf8stage2[(b << 5) | ((cp >> 6) & 31)];
    b = utf8stage1[(b << 3) | ((cp >> 3) & 7)];
    return utf8leaves + utf8stage0[(b << 3) | (cp & 7)];
}
